import requests
import os
import time
from IQCommon.logger import system_log, user_log
from tornado.httputil import url_concat
from IQCommon.exception import get_traceback_message
from IQCommon.common import NOTEBOOK_DIR_PATH, OPEN_API_REQUEST_TIMEOUT, OPEN_API_REQUEST_RETRY_TIMES
OPNE_TOKEN_PATH = os.path.join(NOTEBOOK_DIR_PATH, 'share', 'openapi_token.txt')
def get_token():
    token_value = ''
    if (not os.path.exists(OPNE_TOKEN_PATH)):
        return token_value
    else:
        with open(OPNE_TOKEN_PATH, 'r') as f: token_value = f.read()
        return token_value
def get_open_api_data(url, params, req_type='post'):
    if (req_type == 'post'):
        (error_msg, api_data_tmp) = send_by_post(url, params)
    elif (req_type == 'get'):
        (error_msg, api_data_tmp) = send_by_get(url, params)
    api_data = []
    if (error_msg['error_no'] != 0):
        system_log.warning(f'获取GTN数据为空，详细信息：{error_msg!s}, 返回内容：{api_data_tmp!s}')
        user_log.warning('获取GTN数据为空!')
        return (error_msg, api_data)
    elif ('data' not in api_data_tmp):
        system_log.warning(f'获取GTN数据为空，详细信息：{error_msg!s}, 返回内容：{api_data_tmp!s}')
        user_log.warning('获取GTN数据为空!')
        return ({'error_no': -1, 'error_info': 'GTN数据返回为空'}, api_data)
    elif ('error_no' in api_data_tmp and int(api_data_tmp['error_no']) != 0):
        system_log.warning(f"获取GTN数据失败，详细信息：{api_data_tmp['error_info']!s}, 返回内容：{api_data_tmp!s}")
        user_log.warning(f"获取GTN数据失败，详细信息：{api_data_tmp['error_info']!s}, 返回内容：{api_data_tmp!s}")
        return ({'error_no': -1, 'error_info': api_data_tmp['error_info']}, api_data)
    else:
        return ({'error_no': 0, 'error_info': ''}, api_data_tmp)
def send_by_get(url, params=None):
    tokenValue = get_token()
    if (not tokenValue):
        system_log.warning('ERROR:获取token失败！')
        user_log.warning('ERROR:获取token失败！')
        return ({'error_no': -1, 'error_info': '获取token失败'}, {})
    else:
        headers = {'Authorization': 'Bearer %s' % tokenValue}
        data = params
        real_url = url_concat(url, params)
        request_times = 0
        while request_times <= OPEN_API_REQUEST_RETRY_TIMES:
            try:
                response = requests.get(real_url, headers=headers, data=data, timeout=OPEN_API_REQUEST_TIMEOUT)
                return_data = response.json()
                return ({'error_no': 0, 'error_info': ''}, return_data)
            except BaseException:
                request_times += 1
                if (request_times > OPEN_API_REQUEST_RETRY_TIMES):
                    msg = ('服务器处理异常，错误原因：%s' % get_traceback_message())
                    system_log.warning(msg)
                    user_log.warning(msg)
                    return ({'error_no': -1, 'error_info': msg}, {})
                    break
                else:
                    time.sleep(1)
        else:
            return None
def send_by_post(url, params=None):
    tokenValue = get_token()
    if (not tokenValue):
        system_log.warning('ERROR:获取token失败！')
        user_log.warning('ERROR:获取token失败！')
        return ({'error_no': -1, 'error_info': '获取token失败'}, {})
    else:
        headers = {'Authorization': 'Bearer %s' % tokenValue}
        data = params
        request_times = 0
        while request_times <= OPEN_API_REQUEST_RETRY_TIMES:
            try:
                response = requests.post(url, headers=headers, data=data, timeout=OPEN_API_REQUEST_TIMEOUT)
                return_data = response.json()
                return ({'error_no': 0, 'error_info': ''}, return_data)
            except BaseException:
                request_times += 1
                if (request_times > OPEN_API_REQUEST_RETRY_TIMES):
                    msg = ('服务器处理异常，错误原因：%s' % get_traceback_message())
                    system_log.warning(msg)
                    user_log.warning(msg)
                    return ({'error_no': -1, 'error_info': msg}, {})
                    break
                else:
                    time.sleep(1)
        else:
            return None
